# Find sections and their representative colors
def get_section_colors(grid, separator=3):
    sections = []
    current_section = []
    for col in range(len(grid[0])):
        if col == 0 or grid[0][col] == separator:
            if current_section:
                sections.append(current_section)
                current_section = []
        else:
            # Get non-separator color at this column, averaged
            if col < len(grid) and grid[0][col] != separator:
                section_colors = []
                for row in grid:
                    if col < len(row) and row[col] != separator:
                        section_colors.append(row[col])
                if section_colors:
                    dominant = max(set(section_colors), key=section_colors.count)
                    current_section.append(dominant)
    if current_section:
        sections.append(current_section)
    return sections

# Get representative color for each column (dominant non-3, non-0)
def get_column_representative(grid, row, col):
    colors = []
    for r in grid:
        if col < len(r) and r[col] not in [0, 3]:
            colors.append(r[col])
    if colors:
        dominant = max(set(colors), key=colors.count)
        return dominant
    return None

